USAGE = """Usage: executable [ -cklnoprstvxDELNRSWX ] [ -d fontdirectory ]
              [ -f fontfile ] [ -m smushmode ] [ -w outputwidth ]
              [ -C controlfile ] [ -I infocode ] [ message ]
"""

GERMAN_CODES = [196, 214, 220, 228, 246, 252, 223]

RULE_EQUAL = 1
RULE_UNDERSCORE = 2
RULE_HIERARCHY = 4
RULE_OPPOSITE = 8
RULE_BIGX = 16
RULE_HARDBLANK = 32


class FigletError(Exception):
    pass


class OptionError(FigletError):
    def __init__(self, message: str):
        super().__init__(message)


def c_atoi(text: str) -> int:
    i = 0
    n = len(text)
    while i < n and text[i].isspace():
        i += 1
    sign = 1
    if i < n and text[i] in "+-":
        if text[i] == "-":
            sign = -1
        i += 1
    start = i
    while i < n and text[i].isdigit():
        i += 1
    if i == start:
        return 0
    return sign * int(text[start:i])


def strip_font_extension(name: str) -> str:
    if name.endswith(".flf") or name.endswith(".tlf"):
        return name[:-4]
    return name


def is_option_arg(arg: str) -> bool:
    return len(arg) > 1 and arg.startswith("-")


def option_error(argv0: str, message: str) -> None:
    sys.stderr.write(f"{argv0}: {message}\n")
    sys.stderr.write(USAGE)


def runtime_error(message: str) -> None:
    sys.stderr.write(f"executable: {message}\n")


def get_terminal_width(previous: int) -> int:
    try:
        return os.get_terminal_size(sys.stdout.fileno()).columns
    except OSError:
        return previous


def decode_escape(token: str) -> Optional[int]:
    if token == "":
        return None
    if token.startswith("\\0x") or token.startswith("\\0X"):
        try:
            return int(token[3:], 16)
        except ValueError:
            return None
    if token.startswith("\\-") or (token.startswith("\\") and token[1:].isdigit()):
        body = token[1:]
        try:
            return int(body, 10)
        except ValueError:
            return None
    if token.startswith("\\") and len(token) >= 2:
        return ord(token[1])
    if len(token) == 1:
        return ord(token)
    return None


def decode_spec(token: str) -> List[int]:
    if "-" in token[1:]:
        left, right = token.split("-", 1)
        start = decode_escape(left)
        end = decode_escape(right)
        if start is not None and end is not None and start <= end:
            return list(range(start, end + 1))
    value = decode_escape(token)
    return [] if value is None else [value]


@dataclass
class ControlFile:
    utf8_mode: bool
    mapping: Dict[int, Optional[int]]

    def apply(self, text: str) -> str:
        if not self.mapping:
            return text
        out: List[str] = []
        for ch in text:
            code = ord(ch)
            mapped = self.mapping.get(code)
            if mapped is None:
                out.append(ch)
            elif mapped >= 0:
                out.append(chr(mapped))
        return "".join(out)


def parse_control_file(path: Path) -> ControlFile:
    try:
        lines = path.read_text(encoding="utf-8", errors="surrogateescape").splitlines()
    except OSError as exc:
        raise FigletError(str(exc)) from exc

    utf8_mode = False
    mapping: Dict[int, Optional[int]] = {}
    for raw in lines:
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line == "u":
            utf8_mode = True
            continue
        if line == "h":
            continue
        if line.startswith("flc2"):
            continue
        if line.startswith("g ") or line.startswith("f"):
            continue
        parts = raw.split()
        if not parts:
            continue
        if parts[0] == "t" and len(parts) >= 3:
            src_codes = decode_spec(parts[1])
            dst_codes = decode_spec(parts[2])
            if not src_codes:
                continue
            if not dst_codes:
                mapped_value: Optional[int] = None
                for src in src_codes:
                    mapping[src] = mapped_value
                continue
            if len(dst_codes) == 1:
                for src in src_codes:
                    mapping[src] = dst_codes[0]
                continue
            count = min(len(src_codes), len(dst_codes))
            for idx in range(count):
                mapping[src_codes[idx]] = dst_codes[idx]
            continue
        if parts[0].startswith("0x") and len(parts) >= 2:
            try:
                src = int(parts[0], 16)
                dst = int(parts[1], 16)
            except ValueError:
                continue
            if 0 <= src <= 0x10FFFF:
                mapping[src] = dst
    return ControlFile(utf8_mode=utf8_mode, mapping=mapping)


def locate_font_file(font_name: str, font_dir: str) -> Optional[Path]:
    candidates: List[Path] = []
    candidate_names = [font_name]
    if not (font_name.endswith(".flf") or font_name.endswith(".tlf")):
        candidate_names.extend([font_name + ".flf", font_name + ".tlf"])
    has_path = "/" in font_name or os.sep in font_name
    if has_path:
        candidates.extend(Path(name) for name in candidate_names)
    else:
        for name in candidate_names:
            candidates.append(Path(font_dir) / name)
        for name in candidate_names:
            candidates.append(Path.cwd() / name)
    for path in candidates:
        if path.is_file():
            return path
    return None


def locate_control_file(control_name: str, font_dir: str) -> Optional[Path]:
    candidates: List[Path] = []
    candidate_names = [control_name]
    if not control_name.endswith(".flc"):
        candidate_names.append(control_name + ".flc")
    has_path = "/" in control_name or os.sep in control_name
    if has_path:
        candidates.extend(Path(name) for name in candidate_names)
    else:
        for name in candidate_names:
            candidates.append(Path(font_dir) / name)
        for name in candidate_names:
            candidates.append(Path.cwd() / name)
    for path in candidates:
        if path.is_file():
            return path
    return None


@dataclass
class Glyph:
    rows: List[str]
    width: int


@dataclass
class Font:
    hardblank: str
    height: int
    print_direction: int
    default_layout: int
    glyphs: Dict[int, Glyph]


def normalize_rows(rows: List[str]) -> Glyph:
    width = max((len(row) for row in rows), default=0)
    return Glyph(rows=[row.ljust(width) for row in rows], width=width)


def parse_font(path: Path) -> Font:
    try:
        lines = path.read_text(encoding="utf-8", errors="surrogateescape").splitlines()
    except OSError as exc:
        raise FigletError(str(exc)) from exc
    if not lines:
        raise FigletError("empty font")
    header = lines[0]
    if len(header) < 6 or header[:5] not in ("flf2a", "tlf2a"):
        raise FigletError("invalid font header")
    hardblank = header[5]
    fields = header[6:].strip().split()
    if len(fields) < 5:
        raise FigletError("invalid font header")
    height = int(fields[0])
    old_layout = int(fields[3])
    comment_lines = int(fields[4])
    print_direction = int(fields[5]) if len(fields) > 5 else 0
    full_layout = int(fields[6]) if len(fields) > 6 else None
    if full_layout is not None:
        default_layout = full_layout & 0x7F
    else:
        default_layout = old_layout
    idx = 1 + comment_lines
    codes = list(range(32, 127)) + GERMAN_CODES
    glyphs: Dict[int, Glyph] = {}
    endmark: Optional[str] = None
    for code in codes:
        if idx + height > len(lines):
            raise FigletError("truncated font")
        raw_rows = lines[idx:idx + height]
        idx += height
        if endmark is None:
            first = raw_rows[0]
            endmark = first[-1] if first else "@"
        rows = [row.rstrip(endmark) for row in raw_rows]
        glyphs[code] = normalize_rows(rows)
    while idx < len(lines):
        tag_line = lines[idx].strip()
        idx += 1
        if not tag_line:
            continue
        token = tag_line.split()[0]
        try:
            code = int(token, 0)
        except ValueError:
            break
        if idx + height > len(lines):
            break
        raw_rows = lines[idx:idx + height]
        idx += height
        rows = [row.rstrip(endmark or "@") for row in raw_rows]
        glyphs[code] = normalize_rows(rows)
    return Font(
        hardblank=hardblank,
        height=height,
        print_direction=print_direction,
        default_layout=default_layout,
        glyphs=glyphs,
    )


def font_default_layout(font: Font) -> Tuple[str, int]:
    layout = font.default_layout
    if layout == -1:
        return ("full", 0)
    if layout == 0 or layout == 64:
        return ("kern", 0)
    rules = layout & 63
    if rules == 0:
        return ("overlap", 0)
    return ("smush", rules)


def hierarchy_rank(ch: str) -> Optional[int]:
    if ch == "|":
        return 0
    if ch in "/\\":
        return 1
    if ch in "[]":
        return 2
    if ch in "{}":
        return 3
    if ch in "()":
        return 4
    if ch in "<>":
        return 5
    return None


def controlled_smush(left: str, right: str, hardblank: str, rules: int) -> Optional[str]:
    if left == " ":
        return right
    if right == " ":
        return left
    if left == hardblank or right == hardblank:
        if left == hardblank and right == hardblank and (rules & RULE_HARDBLANK):
            return hardblank
        return None
    if (rules & RULE_EQUAL) and left == right:
        return left
    if rules & RULE_UNDERSCORE:
        if left == "_" and right in r"|/\[]{}()<>":
            return right
        if right == "_" and left in r"|/\[]{}()<>":
            return left
    if rules & RULE_HIERARCHY:
        lrank = hierarchy_rank(left)
        rrank = hierarchy_rank(right)
        if lrank is not None and rrank is not None and lrank != rrank:
            return left if lrank > rrank else right
    if rules & RULE_OPPOSITE:
        if {left, right} == {"[", "]"}:
            return "|"
        if {left, right} == {"{", "}"}:
            return "|"
        if {left, right} == {"(", ")"}:
            return "|"
    if rules & RULE_BIGX:
        if left == "/" and right == "\\":
            return "|"
        if left == "\\" and right == "/":
            return "Y"
        if left == ">" and right == "<":
            return "X"
    return None


def universal_smush(left: str, right: str) -> str:
    if left == " ":
        return right
    if right == " ":
        return left
    return right


@dataclass
class RenderMode:
    kind: str
    rules: int = 0


def merge_char(left: str, right: str, font: Font, mode: RenderMode) -> Optional[str]:
    if mode.kind == "kern":
        if left == " ":
            return right
        if right == " ":
            return left
        return None
    if mode.kind == "overlap":
        return universal_smush(left, right)
    if mode.kind == "smush":
        result = controlled_smush(left, right, font.hardblank, mode.rules)
        if result is not None:
            return result
        return None
    return None


def resolve_render_mode(font: Font, layout_kind: str, explicit_mode: int = 0) -> RenderMode:
    if layout_kind == "full":
        return RenderMode("full")
    if layout_kind == "kern":
        return RenderMode("kern")
    if layout_kind == "overlap":
        return RenderMode("overlap")
    if layout_kind == "force_smush":
        kind, rules = font_default_layout(font)
        if kind == "smush":
            return RenderMode("smush", rules)
        return RenderMode("overlap")
    if layout_kind == "default":
        kind, rules = font_default_layout(font)
        if kind == "full":
            return RenderMode("full")
        if kind == "kern":
            return RenderMode("kern")
        if kind == "overlap":
            return RenderMode("overlap")
        return RenderMode("smush", rules)
    if layout_kind == "explicit":
        if explicit_mode == -2:
            return resolve_render_mode(font, "default")
        if explicit_mode == -1:
            return RenderMode("full")
        if explicit_mode == 0:
            return RenderMode("kern")
        rules = explicit_mode & 63
        if rules == 0:
            return RenderMode("overlap")
        return RenderMode("smush", rules)
    return RenderMode("full")


def max_overlap(left: Glyph, right: Glyph, font: Font, mode: RenderMode) -> int:
    if mode.kind == "full" or left.width == 0 or right.width == 0:
        return 0
    limit = min(left.width, right.width)
    if limit <= 0:
        return 0
    limit -= 1
    best = 0
    for overlap in range(1, limit + 1):
        ok = True
        for row_idx in range(font.height):
            left_part = left.rows[row_idx][left.width - overlap:left.width]
            right_part = right.rows[row_idx][:overlap]
            for a, b in zip(left_part, right_part):
                if merge_char(a, b, font, mode) is None:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            best = overlap
        else:
            break
    return best


def merge_glyphs(left: Glyph, right: Glyph, font: Font, mode: RenderMode) -> Glyph:
    overlap = max_overlap(left, right, font, mode)
    if overlap == 0:
        rows = [left.rows[i] + right.rows[i] for i in range(font.height)]
        return normalize_rows(rows)
    rows: List[str] = []
    for row_idx in range(font.height):
        left_row = left.rows[row_idx]
        right_row = right.rows[row_idx]
        merged_overlap: List[str] = []
        for a, b in zip(left_row[left.width - overlap:left.width], right_row[:overlap]):
            merged = merge_char(a, b, font, mode)
            if merged is None:
                merged = b
            merged_overlap.append(merged)
        rows.append(left_row[:left.width - overlap] + "".join(merged_overlap) + right_row[overlap:])
    return normalize_rows(rows)


def render_text_line(text: str, font: Font, mode: RenderMode, rtl: bool) -> Glyph:
    chars = list(text)
    if rtl:
        chars.reverse()
    glyphs: List[Glyph] = []
    for ch in chars:
        glyph = font.glyphs.get(ord(ch))
        if glyph is not None:
            glyphs.append(glyph)
    if not glyphs:
        return Glyph(["" for _ in range(font.height)], 0)
    current = glyphs[0]
    for glyph in glyphs[1:]:
        current = merge_glyphs(current, glyph, font, mode)
    return current


def apply_alignment(glyph: Glyph, width: int, alignment: str) -> List[str]:
    if glyph.width == 0:
        return ["" for _ in glyph.rows]
    pad = max(width - glyph.width, 0)
    if alignment == "right":
        prefix = pad
    elif alignment == "center":
        prefix = pad // 2
    else:
        prefix = 0
    if prefix <= 0:
        return [row.replace("\x00", " ") for row in glyph.rows]
    return [(" " * prefix) + row for row in glyph.rows]


def logical_lines_from_text(text: str, paragraph_mode: bool) -> List[str]:
    if paragraph_mode and text:
        chars: List[str] = []
        for idx, ch in enumerate(text):
            if (
                ch == "\n"
                and idx > 0
                and text[idx - 1] != "\n"
                and idx + 1 < len(text)
                and text[idx + 1] != " "
            ):
                chars.append(" ")
            else:
                chars.append(ch)
        text = "".join(chars)
    lines = text.split("\n")
    if text.endswith("\n"):
        lines = lines[:-1]
    return lines


def build_cli_text(args: List[str]) -> str:
    segments: List[str] = []
    current_words: List[str] = []
    for arg in args:
        if arg == "":
            segments.append(" ".join(current_words))
            current_words = []
        else:
            current_words.append(arg)
    if current_words:
        segments.append(" ".join(current_words))
    if not current_words and segments == [""]:
        return ""
    return "\n".join(segments)


def apply_german(text: str, enabled: bool) -> str:
    if not enabled:
        return text
    mapping = {
        "[": chr(196),
        "\\": chr(214),
        "]": chr(220),
        "{": chr(228),
        "|": chr(246),
        "}": chr(252),
        "~": chr(223),
    }
    return "".join(mapping.get(ch, ch) for ch in text)


def wrap_rendered_line(
    text: str,
    font: Font,
    mode: RenderMode,
    output_width: int,
    rtl: bool,
) -> List[Glyph]:
    if output_width == 1:
        out: List[Glyph] = []
        iterable = list(text)
        if rtl:
            iterable.reverse()
        for ch in iterable:
            if ch == " ":
                continue
            glyph = font.glyphs.get(ord(ch))
            if glyph is not None:
                out.append(glyph)
        return out
    if output_width <= 0:
        return [render_text_line(text, font, mode, rtl)]
    chars = list(text)
    if rtl:
        chars.reverse()
    lines: List[Glyph] = []
    buffer: List[str] = []
    for ch in chars:
        tentative = "".join(buffer + [ch])
        rendered = render_text_line(tentative, font, mode, False)
        if rendered.width <= output_width or not buffer:
            buffer.append(ch)
            continue
        last_space = -1
        for idx in range(len(buffer) - 1, -1, -1):
            if buffer[idx] == " ":
                last_space = idx
                break
        if last_space > 0:
            segment = "".join(buffer[:last_space])
            if render_text_line(segment, font, mode, False).width <= output_width:
                lines.append(render_text_line(segment, font, mode, False))
                buffer = buffer[last_space + 1:]
            else:
                lines.append(render_text_line("".join(buffer), font, mode, False))
                buffer = []
        else:
            lines.append(render_text_line("".join(buffer), font, mode, False))
            buffer = []
        buffer.append(ch)
    if buffer:
        lines.append(render_text_line("".join(buffer), font, mode, False))
    if rtl:
        fixed: List[Glyph] = []
        for glyph in lines:
            fixed.append(glyph)
        return fixed
    return lines


@dataclass
class Options:
    font_dir: str = DEFAULT_FONT_DIR
    font_name: str = DEFAULT_FONT
    width: int = DEFAULT_WIDTH
    paragraph_mode: bool = False
    alignment: str = "auto"
    direction: str = "font"
    layout_kind: str = "default"
    explicit_mode: int = 0
    infocode: int = -1
    german: bool = False
    control_files: List[str] = None
    message_args: List[str] = None

    def __post_init__(self) -> None:
        if self.control_files is None:
            self.control_files = []
        if self.message_args is None:
            self.message_args = []


def parse_args(argv: List[str]) -> Options:
    opts = Options()
    i = 1
    while i < len(argv):
        arg = argv[i]
        if not is_option_arg(arg):
            opts.message_args.append(arg)
            i += 1
            continue
        j = 1
        while j < len(arg):
            opt = arg[j]
            if opt in "cklnoprstvxDELNRSWX":
                if opt == "c":
                    opts.alignment = "center"
                elif opt == "l":
                    opts.alignment = "left"
                elif opt == "r":
                    opts.alignment = "right"
                elif opt == "x":
                    opts.alignment = "auto"
                elif opt == "p":
                    opts.paragraph_mode = True
                elif opt == "n":
                    opts.paragraph_mode = False
                elif opt == "D":
                    opts.german = True
                elif opt == "E":
                    opts.german = False
                elif opt == "L":
                    opts.direction = "left"
                elif opt == "R":
                    opts.direction = "right"
                elif opt == "X":
                    opts.direction = "font"
                elif opt == "k":
                    opts.layout_kind = "kern"
                elif opt == "W":
                    opts.layout_kind = "full"
                elif opt == "o":
                    opts.layout_kind = "overlap"
                elif opt == "s":
                    opts.layout_kind = "default"
                elif opt == "S":
                    opts.layout_kind = "force_smush"
                elif opt == "t":
                    opts.width = get_terminal_width(opts.width)
                elif opt == "v":
                    opts.infocode = 0
                elif opt == "N":
                    opts.control_files.clear()
                j += 1
                continue
            if opt not in "dfmwCI":
                raise OptionError(f"invalid option -- '{opt}'")
            if j + 1 < len(arg):
                value = arg[j + 1:]
                j = len(arg)
            else:
                i += 1
                if i >= len(argv):
                    raise OptionError(f"option requires an argument -- '{opt}'")
                value = argv[i]
                j = len(arg)
            if opt == "d":
                opts.font_dir = value
            elif opt == "f":
                opts.font_name = value
            elif opt == "w":
                width = c_atoi(value)
                if width > 0:
                    opts.width = width
            elif opt == "m":
                opts.layout_kind = "explicit"
                opts.explicit_mode = c_atoi(value)
            elif opt == "C":
                opts.control_files.append(value)
            elif opt == "I":
                opts.infocode = c_atoi(value)
        i += 1
    return opts


def info_output(opts: Options) -> Optional[str]:
    code = opts.infocode
    if code < 0:
        return None
    if code == 0:
        return VERSION_TEXT + USAGE
    if code == 1:
        return f"{VERSION_INT}\n"
    if code == 2:
        return f"{opts.font_dir}\n"
    if code == 3:
        return f"{strip_font_extension(opts.font_name)}\n"
    if code == 4:
        return f"{opts.width}\n"
    if code == 5:
        return "flf2 tlf2\n"
    if code > 0:
        return ""
    return None


def decode_input(raw: bytes, utf8_mode: bool) -> str:
    if utf8_mode:
        return raw.decode("utf-8", errors="ignore")
    return raw.decode("latin-1")


def effective_direction(opts: Options, font: Font) -> bool:
    if opts.direction == "left":
        return False
    if opts.direction == "right":
        return True
    return font.print_direction != 0


def effective_alignment(opts: Options, rtl: bool) -> str:
    if opts.alignment == "auto":
        return "right" if rtl else "left"
    return opts.alignment


def main(argv: List[str]) -> int:
    try:
        opts = parse_args(argv)
    except OptionError as exc:
        option_error(argv[0], str(exc))
        return 1

    info = info_output(opts)
    if info is not None:
        sys.stdout.write(info)
        return 0

    control_chain: List[ControlFile] = []
    utf8_mode = False
    for control_name in opts.control_files:
        path = locate_control_file(control_name, opts.font_dir)
        if path is None:
            runtime_error(f"{control_name}: Unable to open control file")
            return 1
        control = parse_control_file(path)
        control_chain.append(control)
        utf8_mode = utf8_mode or control.utf8_mode

    font_path = locate_font_file(opts.font_name, opts.font_dir)
    if font_path is None:
        runtime_error(f"{opts.font_name}: Unable to open font file")
        return 1
    try:
        font = parse_font(font_path)
    except FigletError:
        runtime_error(f"{opts.font_name}: Unable to open font file")
        return 1

    rtl = effective_direction(opts, font)
    alignment = effective_alignment(opts, rtl)
    mode = resolve_render_mode(font, opts.layout_kind, opts.explicit_mode)

    if opts.message_args:
        text = build_cli_text(opts.message_args)
